mapper.select:
SELECT o.id, o.shop_id, o.store_id, o.order_id, o.status, o.platform_status, o.buyer, o.goods_amount, o.freight,
       o.discount_amount, o.paid_amount, o.order_time, o.pay_time, o.platform_update_time, o.erp_status, o.erp_order_id,
       o.erp_order_no, o.sales_out_id, o.sales_out_no, o.delivery_status, o.delivery_company_id, o.delivery_company_name,
       o.waybill_no, o.ship_time, o.error_msg, o.sync_time, o.create_time, o.update_time,
       s.name AS shop_name, st.name AS store_name,
       (SELECT MIN(i.title) FROM ch_wx_order_item i WHERE i.wx_order_id = o.id) AS goods_summary,
       (SELECT COUNT(*) FROM ch_wx_order_item i WHERE i.wx_order_id = o.id) AS item_count
FROM ch_wx_order o
JOIN ch_wx_shop s ON s.id = o.shop_id
LEFT JOIN store_info st ON st.id = o.store_id

    o.shop_id = #{q.shopId}
    AND o.store_id = #{q.storeId}
    AND o.status = #{q.status}
    AND o.erp_status = #{q.erpStatus}
    AND o.delivery_status = #{q.deliveryStatus}
    AND o.order_time >= #{q.beginDate}
    AND o.order_time < #{q.endNext}

        AND (o.order_id LIKE CONCAT('%', #{q.keyword}, '%') OR o.erp_order_no LIKE CONCAT('%', #{q.keyword}, '%')
             OR EXISTS (SELECT 1 FROM ch_wx_order_item k WHERE k.wx_order_id = o.id AND k.title LIKE CONCAT('%', #{q.keyword}, '%')))


ORDER BY o.order_time DESC, o.id DESC
